    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(x == v for row in grid for x in row))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] in (7, 8, 9):
                out[r][c] = bg
    # 7 markers placed within/touching colored objects are absorbed into those objects.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 7:
                ns = [grid[y][x] for y, x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0 <= y < h and 0 <= x < w]
                for color in (2, 5, 8):
                    if color in ns:
                        out[r][c] = color
                        break
    return out

