{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-ws0/frozen/seen-3/play/users/u075/system/state/workspace/programs/task-48b289ca.py",
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(x == v for row in grid for x in row))
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            todo = [(r,c)]; seen.add((r,c)); comp=[]
            while todo:
                y,x=todo.pop(); comp.append((y,x))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        yy,xx=y+dy,x+dx
                        if (dy or dx) and 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                            seen.add((yy,xx)); todo.append((yy,xx))
            if len(comp) >= 4:
                objects.append((color, comp))
    out=[[bg]*w for _ in range(h)]
    for color, comp in objects:
        for y,x in comp: out[y][x]=color
    for color, comp in objects:
        r0,r1=min(y for y,x in comp),max(y for y,x in comp)
        c0,c1=min(x for y,x in comp),max(x for y,x in comp)
        for y in range(r0,r1+1):
            for x in range(c0,c1+1):
                if grid[y][x] == bg or out[y][x] == bg:
                    out[y][x]=color
    return out
